const fs=require('fs');
const dir='/Users/kristinarash/.claude/jobs/219ddd5b/tmp/batch133/';
const tax=JSON.parse(fs.readFileSync(dir+'taxonomy.json','utf8'));
const ids=['Q09','Q10','Q11','Q12','Q13','Q14','Q15','Q16'];
const issues=[];
for(const id of ids){
  const raw=fs.readFileSync(dir+'drafts/'+id+'.json','utf8');
  let j; try{ j=JSON.parse(raw);}catch(e){issues.push(id+' PARSE '+e.message);continue;}
  const chk=(k,arr,allowed)=>{for(const v of (Array.isArray(arr)?arr:[arr])){ if(!allowed.includes(v)) issues.push(id+' '+k+' bad value: '+v);} };
  chk('studyDesign',j.studyDesign,tax.studyDesigns);
  chk('primaryDomain',j.primaryDomain,tax.domains);
  chk('domains',j.domains,tax.domains);
  chk('audiences',j.audiences,tax.audiences);
  chk('sports',j.sports,tax.sports);
  chk('populations',j.populations,tax.populations);
  if(!j.domains.includes(j.primaryDomain)) issues.push(id+' primaryDomain not in domains');
  if(j.decision==='INCLUDE' && (j.exclusionReason||j.degradedReason)) issues.push(id+' reason set on INCLUDE');
  const strs=JSON.stringify(j);
  if(/[—–]/.test(strs)) issues.push(id+' em/en dash present');
  if(/[‍‌]/.test(strs)) issues.push(id+' ZWJ present');
  if(/[≤≥]/.test(strs)) issues.push(id+' unicode comparator present');
  if(j.id!==id) issues.push(id+' id mismatch');
  if(!/^10\./.test(j.paper.doi)) issues.push(id+' doi prefix');
  console.log(id, j.decision, j.primaryDomain, '|', j.studyDesign, '|', j.paper.doi, '| year', j.paper.year, '| sentences(limit):', (j.paper.limitations.match(/[.!?](\s|$)/g)||[]).length, '| screen:', (j.screeningLimitations.match(/[.!?](\s|$)/g)||[]).length, '| caution:', (j.synthesisCaution.match(/[.!?](\s|$)/g)||[]).length);
}
console.log('ISSUES:', issues.length? issues.join('\n') : 'none');

