const fs=require('fs');
const dir='/Users/kristinarash/.claude/jobs/219ddd5b/tmp/batch133/';
const tax=JSON.parse(fs.readFileSync(dir+'taxonomy.json','utf8'));
const ids=['Q17','Q18','Q19','Q20','Q21','Q22','Q23','Q24'];
const issues=[];
for(const id of ids){
  let j; try{ j=JSON.parse(fs.readFileSync(dir+'drafts/'+id+'.json','utf8'));}catch(e){issues.push(id+' PARSE '+e.message);continue;}
  const chk=(k,arr,allowed)=>{if(arr==null)return;for(const v of (Array.isArray(arr)?arr:[arr])){ if(!allowed.includes(v)) issues.push(id+' '+k+' bad: '+v);} };
  chk('studyDesign',j.studyDesign,tax.studyDesigns);
  chk('primaryDomain',j.primaryDomain,tax.domains);
  chk('domains',j.domains,tax.domains);
  chk('audiences',j.audiences,tax.audiences);
  chk('sports',j.sports,tax.sports);
  chk('populations',j.populations,tax.populations);
  if(j.decision==='INCLUDE'){
    if(!j.domains.includes(j.primaryDomain)) issues.push(id+' primary not in domains');
    if(j.exclusionReason||j.degradedReason) issues.push(id+' reason on INCLUDE');
    if(!/^10\./.test(j.paper.doi)) issues.push(id+' doi');
    if(!j.paper.citation.includes(j.paper.doi.split('/')[0]) && false) issues.push('');
  } else {
    if(!j.exclusionReason) issues.push(id+' EXCLUDE without reason');
  }
  const s=JSON.stringify(j);
  if(/[—–‍‌≤≥−]/.test(s)) issues.push(id+' dash/ZWJ/unicode');
  if(j.id!==id) issues.push(id+' id');
  console.log(id,j.decision,'|',j.primaryDomain||'-','|',j.studyDesign||'-','|',j.paper?j.paper.doi:'-');
}
console.log('ISSUES:',issues.length?issues.join('; '):'none');

